def build():
    data = {
        "src": SRC,
        "note": NOTE,
        "groups": [{"name": g["name"], "cols": COLS, "rows": g["rows"]} for g in GROUPS],
    }
    js = json.dumps(data, ensure_ascii=False, indent=1)
    out = ("// 符文工房3（rf3）村民支线委托任务。由 _build_rf3_request.py 生成，勿手改。\n"
           "const RF3_REQUEST = " + js + ";\n")
    io.open("js/rf3request.js", "w", encoding="utf-8", newline="\n").write(out)
    n = sum(len(g["rows"]) for g in GROUPS)
    print("groups:", len(GROUPS))
    for g in GROUPS:
        print("  ", g["name"], len(g["rows"]), "条")
    print("total:", n)


if __name__ == "__main__":
    build()
